  ('es_cnmc_circular_3_2020', 'Circular 3/2020, de 15 de enero, de la CNMC, por la que se establece la metodología para el cálculo de los peajes de transporte y distribución de electricidad (consolidated text)', 'The regulator''s circular on the access tariffs: their time periods (article 7), by season, type of day and electrical system.', 'text', 'https://www.boe.es/buscar/act.php?id=BOE-A-2020-1066', null, 'none', array['ES']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:es'),
  ('es_entsoe_eic_codes', 'ENTSO-E — list of Y EIC codes (areas)', 'The list of area codes of the European electricity market, with their functions: bidding zone, control area, scheduling area.', 'text', 'https://eepublicdownloads.blob.core.windows.net/cio-lio/csv/Y_eicCodes.csv', null, 'none', array['ES']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:es'),
  ('es_eurostat_business_prices', 'Eurostat — electricity prices components for non-household consumers, annual (nrg_pc_205_c)', 'Yearly electricity prices of non-household consumers by consumption band and component.', 'text', 'https://ec.europa.eu/eurostat/databrowser/view/nrg_pc_205_c/default/table', null, 'none', array['ES']::text[], '{}'::text[], 'CC-BY-4.0', '© European Union, Eurostat', null, true, 'pack:es'),
