  ('es_ley_24_2013_electricity', 'Ley 24/2013, de 26 de diciembre, del Sector Eléctrico (consolidated text)', 'The electricity act: the subjects of the sector (article 6), among them renewable energy communities and citizen energy communities, and their rights (articles 12 bis and 12 ter).', 'text', 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-13645', null, 'none', array['ES']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:es'),
  ('es_ley_37_1992_vat', 'Ley 37/1992, de 28 de diciembre, del Impuesto sobre el Valor Añadido (consolidated text)', 'The VAT act: the territory where the tax applies (article 3) and its general rate (article 90).', 'text', 'https://www.boe.es/buscar/act.php?id=BOE-A-1992-28740', null, 'none', array['ES']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:es'),
