  ('es_po_10_8_cups', 'Resolución de 16 de noviembre de 2009 — procedimiento de operación 10.8, «Códigos universales para puntos frontera de clientes y productores de régimen especial»', 'The operating procedure, approved by the Secretary of State for Energy, that sets the shape of a CUPS and how its control letters are computed.', 'text', 'https://www.boe.es/boe/dias/2009/11/30/pdfs/BOE-A-2009-19040.pdf', null, 'none', array['ES']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:es'),
  ('es_rd_223_2008_line_categories', 'Real Decreto 223/2008, de 15 de febrero — Reglamento sobre condiciones técnicas y garantías de seguridad en líneas eléctricas de alta tensión, article 3', 'The article that classifies high-voltage lines by their nominal voltage: third, second, first and special category.', 'text', 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-5269', null, 'none', array['ES']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:es'),
