-- identifier_schemes: 4. The identifiers the country issues; a value of identifiers or meters matches the pattern.
insert into identifier_schemes (code, name, description, pattern, url_template, source_code, icd, published_by) values
  ('cups', 'CUPS', 'The universal code of a supply point (código universal de punto de suministro) of the Spanish grid, issued by the distribution operator the point is connected to: ES, four digits of that operator as the transmission operator assigns them, twelve digits of the point, two control letters computed from the sixteen digits (modulo 529, then 23), and optionally a digit and a letter naming a boundary point (F), a main, redundant or check measuring point (P, R, C) or a recorder (X, Y, Z). The code is permanent: it keeps the operator digits of the day it was assigned through later mergers.', '^ES[0-9]{16}[A-Z]{2}([0-9][FPRCXYZ])?$', null, 'es_po_10_8_cups', null, 'pack:es'),
  ('ine', 'Código de municipio INE', 'The five-digit code of a municipality in the statistics office''s register: two digits of the province, three of the municipality, without the control digit the register prints beside them. It is not the postal code.', '^(0[1-9]|[1-4][0-9]|5[0-2])[0-9]{3}$', null, 'ine_municipalities', null, 'pack:es'),
  ('nif', 'NIF de persona jurídica', 'The tax identification number of a company or another legal entity (número de identificación fiscal, formerly CIF): a letter giving its legal form, seven digits, and a control character, a digit or a letter.', '^[ABCDEFGHJNPQRSUVW][0-9]{7}[0-9A-J]$', null, 'es_orden_nif_legal_entities', null, 'pack:es'),
  ('referencia_catastral', 'Referencia catastral', 'The identifier of a property in the cadastre: fourteen characters for the parcel, then four for the property within it and two control letters, twenty in all. The first fourteen characters alone name the parcel, the reference the rules on collective self-consumption read.', '^[0-9A-Z]{14}([0-9]{4}[A-Z]{2})?$', null, 'catastro', null, 'pack:es')
on conflict (code) do update set
  name         = excluded.name,
  description  = excluded.description,
  pattern      = excluded.pattern,
  url_template = excluded.url_template,
  source_code  = excluded.source_code,
  icd          = excluded.icd
where identifier_schemes.published_by = excluded.published_by;

