-- project_kinds: 4. The frames of projects the law of the country defines, each refining a kind of the core.
insert into project_kinds (code, name, description, parent_code, country, source_code, reference, published_by) values
  ('es_autoconsumo_colectivo', 'Autoconsumo colectivo', 'Collective self-consumption: a group of consumers fed, by agreement, from production installations close to their consumption and associated with them, through an internal network or through the grid, sharing the energy by allocation coefficients notified to the distribution operator.', 'collective_self_consumption', 'ES', 'es_rd_244_2019_self_consumption', 'Article 3, letter m) (autoconsumo colectivo) and article 4.3', 'pack:es'),
  ('es_autoconsumo_individual', 'Autoconsumo individual', 'Individual self-consumption: one consumer associated with the production installations close to its consumption.', 'individual_self_consumption', 'ES', 'es_rd_244_2019_self_consumption', 'Article 4.3: self-consumption is individual or collective according to whether one or several consumers are associated with the generation installations', 'pack:es'),
  ('es_comunidad_ciudadana_energia', 'Comunidad ciudadana de energía', 'A citizen energy community: a legal entity of voluntary and open participation, effectively controlled by natural persons, local authorities or small enterprises, whose main purpose is environmental, economic or social benefit for its members or its locality rather than financial return.', 'energy_community', 'ES', 'es_ley_24_2013_electricity', 'Article 6.1, letter k) and article 12 ter', 'pack:es'),
  ('es_comunidad_energias_renovables', 'Comunidad de energías renovables', 'A renewable energy community: a legal entity of open and voluntary participation, effectively controlled by members located near the renewable projects it owns and develops — natural persons, small and medium enterprises or local authorities — whose primary purpose is environmental, economic or social benefit rather than profit.', 'energy_community', 'ES', 'es_ley_24_2013_electricity', 'Article 6.1, letter j) and article 12 bis', 'pack:es')
on conflict (code) do update set
  name        = excluded.name,
  description = excluded.description,
  parent_code = excluded.parent_code,
  country     = excluded.country,
  source_code = excluded.source_code,
  reference   = excluded.reference
where project_kinds.published_by = excluded.published_by;

