      ('energy_price_household'::text, null::text, '{}'::jsonb, '110.8'::jsonb, 'EUR-PER-MegaW-HR'::text, '2025-01-01'::date, null::date, 'es_eurostat_household_prices'::text, 'nrg_pc_204_c, Spain, 2025, band KWH2500-4999, component NRG_SUP: 0.1108 EUR/kWh'::text, 'published'::text),
      ('grid_fees_and_taxes'::text, null::text, '{}'::jsonb, '127.5'::jsonb, 'EUR-PER-MegaW-HR'::text, '2024-01-01'::date, '2025-01-01'::date, 'es_eurostat_household_prices'::text, 'nrg_pc_204_c, Spain, 2024, band KWH2500-4999, components NETC 0.0701 and TAX_FEE_LEV_CHRG 0.0574 EUR/kWh, VAT excluded'::text, 'published'::text),
      ('grid_fees_and_taxes'::text, null::text, '{}'::jsonb, '153'::jsonb, 'EUR-PER-MegaW-HR'::text, '2025-01-01'::date, null::date, 'es_eurostat_household_prices'::text, 'nrg_pc_204_c, Spain, 2025, band KWH2500-4999, components NETC 0.0712 and TAX_FEE_LEV_CHRG 0.0818 EUR/kWh, VAT excluded'::text, 'published'::text),
      ('offpeak_hours'::text, null::text, '{"segment":"residential"}'::jsonb, '[["00:00","08:00"]]'::jsonb, 'hours'::text, '2020-01-25'::date, null::date, 'es_cnmc_circular_3_2020'::text, 'Article 7.3, the three periods of the 2.0 TD tariff, period 3 (valle): 0 h to 8 h from Monday to Friday on the peninsula, the Balearic and Canary Islands, Ceuta and Melilla, and every hour of Saturdays, Sundays, 6 January and the national holidays of fixed date'::text, 'published'::text),
      ('offpeak_hours'::text, null::text, '{}'::jsonb, null::jsonb, 'hours'::text, '2020-01-25'::date, null::date, 'es_cnmc_circular_3_2020'::text, 'Article 7: the periods depend on the access tariff — three periods for the energy of the 2.0 TD tariff, six (P1 to P6) by season, type of day and electrical system for every other tariff'::text, 'published'::text),
      ('sharing_perimeter'::text, null::text, '{"project_kind":"es_autoconsumo_colectivo"}'::jsonb, '["same_substation","radius_around_producer"]'::jsonb, 'list'::text, '2026-03-22'::date, null::date, 'es_rd_244_2019_self_consumption'::text, 'Article 3, letter g), as amended by the Real Decreto-ley 7/2026, final provision 14.1, in force from 22 March 2026: a production installation is close to the consumption through the grid when it is connected to any low-voltage network fed from the same transformer station (ii), or within 500 metres of the associated consumers (iii); the same cadastral reference (iv) is not a criterion of the model yet'::text, 'published'::text),
      ('sharing_radius_m'::text, null::text, '{"project_kind":"es_autoconsumo_colectivo","device_type":"solar"}'::jsonb, '5000'::jsonb, 'M'::text, '2026-03-22'::date, null::date, 'es_rd_244_2019_self_consumption'::text, 'Article 3, letter g), iii), second paragraph, as amended by the Real Decreto-ley 7/2026, final provision 14.1: a photovoltaic installation of up to 5 MW connected to the consumers through the transmission or distribution lines, at a distance below 5 000 metres from them'::text, 'published'::text),
      ('sharing_radius_m'::text, null::text, '{"project_kind":"es_autoconsumo_colectivo","device_type":"wind"}'::jsonb, '5000'::jsonb, 'M'::text, '2026-03-22'::date, null::date, 'es_rd_244_2019_self_consumption'::text, 'Article 3, letter g), iii), second paragraph, as amended by the Real Decreto-ley 7/2026, final provision 14.1: a wind installation of up to 5 MW connected to the consumers through the transmission or distribution lines, at a distance below 5 000 metres from them'::text, 'published'::text),
      ('sharing_radius_m'::text, null::text, '{"project_kind":"es_autoconsumo_colectivo"}'::jsonb, '500'::jsonb, 'M'::text, '2026-03-22'::date, null::date, 'es_rd_244_2019_self_consumption'::text, 'Article 3, letter g), iii), as amended by the Real Decreto-ley 7/2026, final provision 14.1: at a distance below 500 metres from the associated consumers, measured between the metering equipment in orthogonal projection on the plan'::text, 'published'::text),
      ('sharing_settlement_period'::text, null::text, '{"project_kind":"es_autoconsumo_colectivo"}'::jsonb, '"PT1H"'::jsonb, 'ISO8601-duration'::text, '2019-04-07'::date, null::date, 'es_rd_244_2019_self_consumption'::text, 'Annex I.1: the net generated energy is allocated to each consumer hour by hour, by an hourly coefficient whose sum over the consumers is one for every hour of the billing period'::text, 'published'::text),
      ('vat_rate_electricity'::text, null::text, '{}'::jsonb, '0.21'::jsonb, 'UNITLESS'::text, '2025-01-01'::date, '2026-03-22'::date, 'es_ley_37_1992_vat'::text, 'Article 90.Uno: the general rate of 21 %; it applies to electricity from 1 January 2025, when the temporary rate of 10 % of the Real Decreto-ley 8/2023, article 21, ended on 31 December 2024; until 22 March 2026, when the Real Decreto-ley 7/2026, article 42, lowered it again for some contracts'::text, 'published'::text),
      ('vat_rate_electricity'::text, 'ES-CE'::text, '{}'::jsonb, null::jsonb, 'UNITLESS'::text, '2025-01-01'::date, null::date, 'es_ley_37_1992_vat'::text, 'Article 3.Dos.1.º a): Ceuta is outside the territory where VAT applies; a supply there bears the city''s own indirect tax (IPSI), which this pack does not hold'::text, 'published'::text),
      ('vat_rate_electricity'::text, 'ES-CN'::text, '{}'::jsonb, null::jsonb, 'UNITLESS'::text, '2025-01-01'::date, null::date, 'es_ley_37_1992_vat'::text, 'Article 3.Dos.1.º b): the Canary Islands are outside the territory where VAT applies; a supply there bears the Canary Islands'' general indirect tax (IGIC), which this pack does not hold'::text, 'published'::text),
      ('vat_rate_electricity'::text, 'ES-ML'::text, '{}'::jsonb, null::jsonb, 'UNITLESS'::text, '2025-01-01'::date, null::date, 'es_ley_37_1992_vat'::text, 'Article 3.Dos.1.º a): Melilla is outside the territory where VAT applies; a supply there bears the city''s own indirect tax (IPSI), which this pack does not hold'::text, 'published'::text),
      ('voltage_levels'::text, null::text, '{}'::jsonb, '[{"code":"bt","name":"Baja tensión","min_kv":0,"max_kv":1},{"code":"at_tercera","name":"Alta tensión, tercera categoría","min_kv":1,"max_kv":30},{"code":"at_segunda","name":"Alta tensión, segunda categoría","min_kv":30,"max_kv":66},{"code":"at_primera","name":"Alta tensión, primera categoría","min_kv":66,"max_kv":220},{"code":"at_especial","name":"Alta tensión, categoría especial","min_kv":220,"max_kv":400}]'::jsonb, 'KiloV'::text, '2008-09-19'::date, null::date, 'es_rd_223_2008_line_categories'::text, 'Article 3: third category above 1 kV up to 30 kV, second above 30 kV up to 66 kV, first above 66 kV and below 220 kV, special from 220 kV (and lower lines of the transmission grid); a line above 400 kV needs the voltage set by the administration. Low voltage is everything up to 1 kV. A line of exactly 220 kV is of the special category, where these levels, which include their upper bound, read the first. The decree was published on 19 March 2008 and entered into force six months later (final provision three)'::text, 'published'::text)
  ),
  problems (problem) as (
    select format('attribute_type_unknown: %s is not an attribute_types code', p.attribute_type)
      from pack p
     where not exists (select 1 from attribute_types d where d.code = p.attribute_type)
    union all
    select format('unit_mismatch: %s is stored in %s and the pack says %s', p.attribute_type, u.unit, p.unit)
      from pack p
      join attribute_types d on d.code = p.attribute_type
      join quantities q on q.code = d.quantity_code
      cross join lateral (select quantity_unit(q.code, (select c.currency from countries c where c.code = 'ES')) as unit) u
     where u.unit <> p.unit
    union all
    select format('value_edited: %s%s from %s holds %s and the pack says %s; close it with valid_to and add a row',
                  p.attribute_type, coalesce(' (' || nullif(concat_ws(', ', p.region, nullif(p.condition, '{}')::text), '') || ')', ''), p.valid_from,
                  coalesce(x.value::text, 'null'), coalesce(p.value::text, 'null'))
      from pack p
      join defaults x
        on x.country = 'ES' and x.attribute_type = p.attribute_type
       and x.region is not distinct from p.region and x.valid_from = p.valid_from
       and x.condition = p.condition
     where x.value is distinct from p.value
  ),
  written as (
    insert into defaults (attribute_type, country, region, condition, value, valid_from, valid_to,
                          source_code, reference, quality, published_by)
    select p.attribute_type, 'ES', p.region, p.condition, p.value, p.valid_from, p.valid_to,
           p.source_code, p.reference, p.quality, 'pack:es'
      from pack p
     where not exists (select 1 from problems)
    on conflict (country, region, attribute_type, condition, valid_from) do update set
      valid_to    = excluded.valid_to,
      source_code = excluded.source_code,
      reference   = excluded.reference,
      quality     = excluded.quality
    returning 1
  )
  select string_agg(problem, '; ' order by problem) into refused from problems;
  if refused is not null then
    raise exception '%', refused;
  end if;
end
$seed$;
